// Explicit Jira assignee mapping for names/usernames that do not match.
const defaultJiraMemberAliases={
  '00125054':['minhtnh2'],
  '00248973':['manhtc']
};
function jiraMemberAliases(){try{return{...defaultJiraMemberAliases,...JSON.parse(localStorage.getItem('backend-jira-member-map')||'{}')}}catch{return{...defaultJiraMemberAliases}}}
function jiraTaskMember(task){const aliases=jiraMemberAliases(),account=String(task.accountId||'').toLowerCase(),display=personKey(task.member);return members.find(member=>(aliases[member.id]||[]).some(alias=>String(alias).trim().toLowerCase()===account||personKey(alias)===display)||personKey(member.name)===display||member.id===task.accountId)||null}
const jiraSyncWithMapping=syncRealJiraFromBackend;
syncRealJiraFromBackend=async function(){const base=(localStorage.getItem('backend-kpi-api-base')||'http://localhost:8788').replace(/\/$/,''),button=document.querySelector('#syncRealJira');if(button){button.disabled=true;button.textContent='Đang đồng bộ...'}try{const query=new URLSearchParams({maxResults:'1000',maxIssues:'1000',jql:periodJql()}),response=await fetch(`${base}/api/sync?${query}`),data=await response.json();if(!response.ok||data.error)throw new Error(data.error||'Backend không phản hồi');const issues=(data.issues||[]).map(task=>{const member=jiraTaskMember(task);return member?{...task,member:member.name,accountId:member.id,jiraAccountId:task.accountId}:task});state.jiraIssues=issues;let mapped=0;members.forEach(member=>{const matched=issues.filter(task=>task.accountId===member.id||personKey(task.member)===personKey(member.name));if(!matched.length)return;mapped+=matched.length;const committed=matched.length,closed=matched.filter(task=>task.done).length,committedPoints=matched.reduce((sum,task)=>sum+task.storyPoints,0),deliveredPoints=matched.filter(task=>task.done).reduce((sum,task)=>sum+task.storyPoints,0),rate=committed?closed/committed:0,group=evalGroup(member),criteria=criteriaFor(group);state[member.id]??={};state[member.id].workload={committed,closed,committedPoints,deliveredPoints};state[member.id][group]??={};state[member.id][group].scores??=[];if(criteria.length){const max=criteria[0][1];state[member.id][group].scores[0]=rate>=.9?max:rate>=.75?max*.6:rate>=.6?max*.267:0}state[member.id][group].taskLinks??={};state[member.id][group].taskLinks[0]=matched.map(task=>task.key)});save(`Đồng bộ ${issues.length} task Jira`);render();toast(`Đã sync ${issues.length} task · map ${mapped} task theo account/name`)}catch(error){toast(`Không đồng bộ được Jira: ${error.message}`)}finally{if(button){button.disabled=false;button.textContent='Đồng bộ Jira Data Center'}}};
const settingsWithMapping=renderSettings;
renderSettings=function(){settingsWithMapping();const form=document.querySelector('#jiraSettings');if(!form)return;form.querySelector('.jira-member-map')?.remove();const aliases=jiraMemberAliases();const note=form.querySelector('.settings-note');note?.insertAdjacentHTML('beforebegin',`<details class="jira-member-map"><summary>Mapping member Jira</summary><p>Nhập Jira username/account hoặc email, ngăn cách bằng dấu phẩy. Mapping này được ưu tiên trước khi so khớp tên.</p><div class="jira-map-list">${members.map(member=>`<label><span><b>${member.name}</b><small>${member.id} · ${member.group}</small></span><input data-jira-alias="${member.id}" value="${(aliases[member.id]||[]).join(', ')}" placeholder="Ví dụ: minhtnh2"></label>`).join('')}</div><button type="button" class="btn btn-primary" id="saveJiraMapping">Lưu mapping member</button></details>`);form.querySelector('#saveJiraMapping').onclick=()=>{const map={};form.querySelectorAll('[data-jira-alias]').forEach(input=>{const values=input.value.split(',').map(value=>value.trim()).filter(Boolean);if(values.length)map[input.dataset.jiraAlias]=values});localStorage.setItem('backend-jira-member-map',JSON.stringify(map));toast('Đã lưu mapping member Jira');renderSettings()}};
render();
